export function tUi(locale: string | undefined, en: string): string {
  const row = STATIC_UI[en];
  if (!row) return en;
  const loc = locale || 'en';
  return row[loc] ?? row.en ?? en;
}

export function tCategory(locale: string | undefined, slug: string | undefined): string {
  if (!slug) return 'Woody Blog';
  const loc = locale || 'en';
  const row = CATEGORY_LABELS[slug];
  if (row) return row[loc] ?? row.en ?? slug;
  return slug.split('-').map((p) => p.charAt(0).toUpperCase() + p.slice(1)).join(' ');
}
